create extension if not exists pgcrypto;
create table if not exists public.club_admins(user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.members(id uuid primary key default gen_random_uuid(), name text not null, usn text, designation text, wing text, bio text, photo_url text, sort_order integer not null default 100, published boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.events(id uuid primary key default gen_random_uuid(), title text not null, event_date date, description text, published boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.announcements(id uuid primary key default gen_random_uuid(), title text not null, body text not null, published boolean not null default true, created_at timestamptz not null default now());
alter table public.club_admins enable row level security;
alter table public.members enable row level security;
alter table public.events enable row level security;
alter table public.announcements enable row level security;
create or replace function public.is_raismeanvaya_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.club_admins where user_id=auth.uid()); $$;
create policy "Admins can read admin list" on public.club_admins for select to authenticated using(user_id=auth.uid());
create policy "Read published members" on public.members for select to anon,authenticated using(published=true or public.is_raismeanvaya_admin());
create policy "Admins manage members" on public.members for all to authenticated using(public.is_raismeanvaya_admin()) with check(public.is_raismeanvaya_admin());
create policy "Read published events" on public.events for select to anon,authenticated using(published=true or public.is_raismeanvaya_admin());
create policy "Admins manage events" on public.events for all to authenticated using(public.is_raismeanvaya_admin()) with check(public.is_raismeanvaya_admin());
create policy "Read published announcements" on public.announcements for select to anon,authenticated using(published=true or public.is_raismeanvaya_admin());
create policy "Admins manage announcements" on public.announcements for all to authenticated using(public.is_raismeanvaya_admin()) with check(public.is_raismeanvaya_admin());
grant usage on schema public to anon,authenticated;
grant select on public.members,public.events,public.announcements to anon,authenticated;
grant insert,update,delete,select on public.members,public.events,public.announcements to authenticated;
grant select on public.club_admins to authenticated;
